<?php
if (!defined('ABSPATH')) exit;
class TAPT_Public {
 public function __construct(){add_shortcode('ta_personal_timba',[$this,'shortcode']);add_action('wp_enqueue_scripts',[$this,'assets']);}
 public function assets(){wp_register_style('tapt-public',TAPT_URL.'assets/css/public.css',[],TAPT_VERSION);}
 public function shortcode(){wp_enqueue_style('tapt-public');global $wpdb;$t=TAPT_DB::tables();$lots=TAPT_DB::lotteries();if(!$lots)return '<p>No hay loterías activas.</p>';$lid=absint($_GET['tapt_lottery']??$lots[0]->id);$lot=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$t['lotteries']} WHERE id=%d AND is_active=1",$lid))?:$lots[0];$mods=TAPT_DB::modalities($lot->id);$mid=absint($_GET['tapt_modality']??($mods[0]->id??0));$limit=sanitize_text_field($_GET['tapt_limit']??'25');$contest=sanitize_text_field($_GET['tapt_draw']??'');$allowed=['25','50','100','200','500','all'];if(!in_array($limit,$allowed,true))$limit='25';$where=$wpdb->prepare('d.lottery_id=%d',$lot->id);if($mid)$where.=$wpdb->prepare(' AND r.modality_id=%d',$mid);if($contest!=='')$where.=$wpdb->prepare(' AND d.contest_number=%s',$contest);$sql="SELECT d.id,d.contest_number,d.draw_date,r.modality_id,GROUP_CONCAT(r.number_value ORDER BY r.number_value) nums FROM {$t['draws']} d JOIN {$t['results']} r ON r.draw_id=d.id WHERE $where GROUP BY d.id,r.modality_id ORDER BY d.draw_date DESC,d.id DESC";if($limit!=='all')$sql.=' LIMIT '.intval($limit);$rows=$wpdb->get_results($sql);$modmap=[];foreach($mods as $m)$modmap[$m->id]=$m;$freq=[];$recent=array_slice($rows,0,10);foreach($recent as $x)foreach(array_map('intval',explode(',',$x->nums)) as $n)$freq[$n]=($freq[$n]??0)+1;
 ob_start();?><div class="tapt"><h2>TA Personal Timba — Vista Matriz</h2><form class="tapt-filters" method="get"><label>Lotería<select name="tapt_lottery"><?php foreach($lots as $l):?><option value="<?=esc_attr($l->id)?>" <?=$l->id==$lot->id?'selected':''?>><?=esc_html($l->name)?></option><?php endforeach;?></select></label><label>Modalidad<select name="tapt_modality"><option value="0">Todas</option><?php foreach($mods as $m):?><option value="<?=esc_attr($m->id)?>" <?=$m->id==$mid?'selected':''?>><?=esc_html($m->name)?></option><?php endforeach;?></select></label><label>Nº sorteo<input name="tapt_draw" value="<?=esc_attr($contest)?>"></label><label>Mostrar<select name="tapt_limit"><?php foreach($allowed as $v):?><option <?=$v===$limit?'selected':''?> value="<?=esc_attr($v)?>"><?=$v==='all'?'Todos':esc_html($v)?></option><?php endforeach;?></select></label><button>Filtrar</button></form><div class="tapt-scroll"><table class="tapt-matrix"><thead><tr><th class="sticky-a">Sorteo</th><th class="sticky-b">Fecha</th><?php for($n=$lot->number_min;$n<=$lot->number_max;$n++):?><th><?=sprintf('%02d',$n)?></th><?php endfor;?></tr></thead><tbody><?php foreach($rows as $x):$nums=array_flip(array_map('intval',explode(',',$x->nums)));$m=$modmap[$x->modality_id]??null;?><tr><td class="sticky-a"><strong><?=esc_html($x->contest_number)?></strong><small><?=esc_html($m->name??'')?></small></td><td class="sticky-b"><?=esc_html(date_i18n('d/m/Y',strtotime($x->draw_date)))?></td><?php for($n=$lot->number_min;$n<=$lot->number_max;$n++):$hit=isset($nums[$n]);$hot=($freq[$n]??0)>=4;?><td><span class="ball <?=$hit?'hit':''?> <?=$hit&&$hot?'hot':''?>" style="<?=$hit&&$m?'--mod:'.esc_attr($m->color):''?>"><?=sprintf('%02d',$n)?></span></td><?php endfor;?></tr><?php endforeach;?></tbody></table></div><p class="tapt-legend">● Resultado · <span class="hotkey">●</span> Frecuencia llamativa: 4+ apariciones en los últimos 10 resultados de la selección.</p></div><?php return ob_get_clean();}
}
